/** Exact Android Java sources plus authoritative R.java generated by AAPT2. */
const validName=/^[A-Za-z_][A-Za-z_0-9]*$/;
export function javaSourcePaths(analysis){
 const files=analysis?.javaPaths??[];
 const main=files.filter(p=>/(?:^|\/)src\/main\/(?:java|kotlin)\/.*\.java$/.test(p));
 if(main.length!==analysis?.java)
  throw Error('Projet Java partiel : '+main.length+'/'+analysis?.java+' classes sous src/main. Les tests sont exclus.');
 if(main.length>250)throw Error('Trop de fichiers Java (maximum 250).');
 if(!main.length)throw Error('Aucun fichier Java principal.');
 const names=new Set();
 for(const path of main){
  const name=path.split('/').at(-1);
  if(!/^[A-Za-z_$][\w$]*\.java$/.test(name))throw Error('Nom Java invalide : '+path);
  if(names.has(name))throw Error('Fichiers Java ayant le même nom : '+name+
   '. Utilise un projet avec des noms uniques pour cette première version.');
  names.add(name);
 }
 if(names.has('R.java'))throw Error('R.java source présent : conflit avec R réel généré par AAPT2.');
 return main;
}
export function javaCompileProfile(analysis,catalog){
 if(!analysis||!catalog||!Array.isArray(catalog.artifacts))throw Error('Catalogue Java Android indisponible.');
 if((Number(analysis.kotlin)||0)!==0)throw Error('Projet Java/Kotlin mixte non encore compilable.');
 if(!catalog.javaCompiler?.relative||!catalog.javaCompiler.sha256)
  throw Error('Compilateur ECJ Java non encore publié dans le catalogue Android.');
 if(analysis.unresolvedDependencies?.length)
  throw Error('Dépendances Gradle non résolues (aliases/modules/fichiers) : '+analysis.unresolvedDependencies.join(', '));
 const required=new Set(catalog.requiredCoordinates||[]);
 const declared=analysis.dependencies||[];
 const adsRequested=['com.applovin:applovin-sdk:+','com.google.android.gms:play-services-ads-identifier:18.2.0'];
 const adsProfile=adsRequested.every(x=>declared.includes(x));
 if(adsProfile){
  const ads=catalog.trainManagerAds;
  if(!ads||!ads.selectedAppLovin)
   throw Error('Dépendances MAX/GMS non résolues dans le catalogue Maven publié.');
  if(ads.manifestResourceMergeSupported!==true)
   throw Error('AppLovin MAX '+ads.selectedAppLovin+' et Google Ads sont maintenant résolus ('+
    ads.artifacts+' artefacts Maven dont '+ads.aars+' AAR et '+ads.aarResources+
    ' ressources Android), mais la fusion des manifestes, ressources et R des AAR'+
    ' n’est pas encore intégrée au navigateur. Compilation suspendue pour éviter un APK incomplet.');
 }
 const missing=declared.filter(x=>!required.has(x));
 if(missing.length)throw Error('Dépendances Gradle Java absentes du moteur actuel : '+missing.join(', ')+
  '. Elles doivent être résolues, avec leurs classes et ressources, avant de compiler et signer TrainManager.');
 const namespace=analysis.namespace!=='Non précisé'?analysis.namespace:analysis.packageName;
 if(!/^[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+$/.test(namespace||''))
  throw Error('Namespace/package Android manquant dans build.gradle ou AndroidManifest.xml.');
 const minSdk=Number(analysis.minSdk);
 if(!Number.isInteger(minSdk)||minSdk<21||minSdk>36)
  throw Error('minSdk Android absent ou hors plage 21–36.');
 if(!Number.isInteger(Number(analysis.sdk))||Number(analysis.sdk)>36||Number(analysis.sdk)<21)
  throw Error('compileSdk Android absent ou non pris en charge (SDK 21–36).');
 return {paths:javaSourcePaths(analysis),namespace,minSdk};
}
export function realJavaR(namespace,ids){
 if(!/^[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+$/.test(namespace||''))
  throw Error('Namespace Java invalide.');
 if(!ids||!Object.keys(ids).length)throw Error('IDs AAPT2 absents : R.java ne peut pas être généré.');
 const groups=new Map();
 for(const [id,value] of Object.entries(ids)){
  const [kind,name,...extra]=id.split('/');
  if(extra.length||!validName.test(kind||'')||!validName.test(name||''))
   throw Error('Symbole AAPT2 non représentable en Java : '+id);
  if(Array.isArray(value)){
   if(kind!=='styleable'||!value.every(n=>Number.isInteger(n)&&n>=0&&n<=0xffffffff))
    throw Error('Valeur R.styleable invalide : '+id);
  }else if(!Number.isInteger(value)||value<0||value>0xffffffff)
    throw Error('ID AAPT2 non numérique : '+id);
  if(!groups.has(kind))groups.set(kind,[]);
  groups.get(kind).push({name,value});
 }
 let code='package '+namespace+';\n\n/** Identifiants réels du R.txt AAPT2. */\npublic final class R {\n private R() {}\n';
 for(const [kind,entries] of [...groups].sort(([a],[b])=>a.localeCompare(b))){
  code+=' public static final class '+kind+' {\n  private '+kind+'() {}\n';
  for(const {name,value} of entries.sort((a,b)=>a.name.localeCompare(b.name))){
   const lit=n=>'0x'+n.toString(16);
   code+=Array.isArray(value)
    ?'  public static final int[] '+name+' = new int[]{'+value.map(lit).join(',')+'};\n'
    :'  public static final int '+name+' = '+(kind==='styleable'?String(value):lit(value))+';\n';
  }
  code+=' }\n';
 }
 return code+'}\n';
}
